    forexBoxSentence1: " \u062A\u0648\u0641\u0631 \u0645\u0646\u0635\u0629 \u0647\u0627\u0631\u0645\u0648\u0641\u0633\u062A \u0643\u0627\u0628\u064A\u062A\u0627\u0644 \u0631\u0627\u0641\u0639\u0629 \u0645\u0627\u0644\u064A\u0629 \u0645\u062D\u0633\u0651\u0646\u0629 \u0644\u0645\u0633\u0627\u0639\u062F\u0629 \u0627\u0644\u0645\u0633\u062A\u062B\u0645\u0631\u064A\u0646 \u0639\u0644\u0649 \u0627\u0644\u0627\u0633\u062A\u0641\u0627\u062F\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0645\u0646 \u0641\u0631\u0635 \u0633\u0648\u0642 \u0627\u0644\u0641\u0648\u0631\u0643\u0633 \u0627\u0644\u0639\u0627\u0644\u0645\u064A.",
    forexBoxSentence2: "\u0631\u0627\u0641\u0639\u0629 \u0645\u0627\u0644\u064A\u0629 \u0645\u0631\u0646\u0629.",
    forexBoxSentence3: "1:2000\u0627\u0633\u062A\u0645\u062A\u0639 \u0628\u0631\u0627\u0641\u0639\u0629 \u0645\u0627\u0644\u064A\u0629 \u062A\u0635\u0644 ",
    forexBoxSentence4: "\u0633\u0627\u0639\u0629. 24 \u062A\u062F\u0627\u0648\u0644 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631",
    forexBoxSentence5: "\u0633\u0648\u0642 \u0641\u0648\u0631\u0643\u0633 \u0639\u0627\u0644\u0645\u064A \u064A\u0639\u0645\u0644 \u062F\u0648\u0646 \u062A\u0648\u0642\u0641 \u0645\u0639 \u0633\u0627\u0639\u0627\u062A \u062A\u062F\u0627\u0648\u0644 \u0645\u0631\u0646\u0629.",
    forexBoxSentence6: "\u0628\u062F\u0648\u0646 \u0639\u0645\u0648\u0644\u0627\u062A \u0648\u062A\u0643\u0644\u0641\u0629 \u0645\u0646\u062E\u0641\u0636\u0629.",
    forexBoxSentence7: "\u0644\u0627 \u064A\u062A\u0645 \u0641\u0631\u0636 \u0623\u064A \u0639\u0645\u0648\u0644\u0627\u062A \u062D\u064A\u062B \u064A\u062A\u0645 \u062A\u062D\u0642\u064A\u0642 \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u0645\u0646 \u0641\u0631\u0648\u0642 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0641\u0642\u0637.",
    forexBoxSentence8: "\u062A\u062F\u0627\u0648\u0644 \u062B\u0646\u0627\u0626\u064A \u0627\u0644\u0627\u062A\u062C\u0627\u0647 \u0628\u0639\u062F\u0627\u0644\u0629 \u0648\u0634\u0641\u0627\u0641\u064A\u0629",
    forexBoxSentence9: "\u0625\u0645\u0643\u0627\u0646\u064A\u0629 \u0627\u0644\u0627\u0633\u062A\u0641\u0627\u062F\u0629 \u0645\u0646 \u062A\u062D\u0631\u0643\u0627\u062A \u0627\u0644\u0633\u0648\u0642 \u0635\u0639\u0648\u062F\u064B\u0627 \u0648\u0647\u0628\u0648\u0637\u064B\u0627",
    forexBoxSentence10: "\u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0633\u0648\u064A\u0629 \u0627\u0644\u0641\u0648\u0631\u064A\u0629",
    forexBoxSentence11: "\u064A\u062A\u0645\u062A\u0639 \u0633\u0648\u0642 \u0627\u0644\u0641\u0648\u0631\u0643\u0633 \u0628\u0633\u064A\u0648\u0644\u0629 \u0639\u0627\u0644\u064A\u0629 \u0648\u0633\u0647\u0648\u0644\u0629 \u0641\u064A \u062A\u0646\u0641\u064A\u0630 \u0627\u0644\u0635\u0641\u0642\u0627\u062A",
    forexBoxSentence12: "\u0641\u0631\u064A\u0642 \u062F\u0639\u0645 \u0645\u062A\u0639\u062F\u062F \u0627\u0644\u0644\u063A\u0627\u062A",
    forexBoxSentence13: "\u0646\u0642\u062F\u0645 \u062F\u0639\u0645\u064B\u0627 \u0641\u0646\u064A\u064B\u0627 \u0645\u062A\u0645\u064A\u0632\u064B\u0627 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631 \u0627\u0644\u0633\u0627\u0639\u0629 \u0637\u0648\u0627\u0644 \u0623\u064A\u0627\u0645 \u0627\u0644\u0623\u0633\u0628\u0648\u0639",
    symbol: "\u0627\u0644\u0631\u0645\u0632",
    ask: "\u0633\u0639\u0631 \u0627\u0644\u0634\u0631\u0627\u0621",
    bid: "\u0633\u0639\u0631 \u0627\u0644\u0628\u064A\u0639",
    spread: "\u0641\u0631\u0642 \u0627\u0644\u0633\u0639\u0631",
    contractSize: "\u062D\u062C\u0645 \u0627\u0644\u0639\u0642\u062F",
    leverage: "\u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629",
    tradingHours: "\u0633\u0627\u0639\u0627\u062A \u0627\u0644\u062A\u062F\u0627\u0648\u0644",
    forexTextBox: "\u0641\u0631\u0648\u0642 \u0627\u0644\u0623\u0633\u0639\u0627\u0631",
    forexTextBox1: "\u0641\u0631\u0648\u0642 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0645\u062A\u063A\u064A\u0631\u0629. \u0627\u0644\u0642\u064A\u0645 \u0627\u0644\u0645\u0639\u0631\u0648\u0636\u0629 \u0641\u064A \u0627\u0644\u062C\u062F\u0627\u0648\u0644 \u0647\u064A \u0644\u0623\u063A\u0631\u0627\u0636 \u0645\u0631\u062C\u0639\u064A\u0629 \u0641\u0642\u0637 \u0648\u062A\u0639\u0643\u0633 \u0646\u0637\u0627\u0642 \u0641\u0631\u0648\u0642 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0627\u0644\u0633\u0627\u0628\u0642\u0629. \u064A\u0631\u062C\u0649 \u0627\u0644\u0631\u062C\u0648\u0639 \u0625\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u062A\u062F\u0627\u0648\u0644 \u0644\u0645\u0639\u0631\u0641\u0629 \u0641\u0631\u0648\u0642 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0627\u0644\u0641\u0639\u0644\u064A\u0629 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u062D\u0642\u064A\u0642\u064A.",
    forexTextBox2: "\u0627\u0644\u062A\u0628\u064A\u064A\u062A",
    forexTextBox3: "\u064A\u062A\u0645 \u062A\u0637\u0628\u064A\u0642 \u0631\u0633\u0648\u0645 \u0627\u0644\u062A\u0628\u064A\u064A\u062A \u0639\u0644\u0649 \u062C\u0645\u064A\u0639 \u0627\u0644\u0635\u0641\u0642\u0627\u062A \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629 \u0644\u0644\u064A\u0648\u0645 \u0627\u0644\u062A\u0627\u0644\u064A. \u0641\u064A \u062D\u0627\u0644 \u0643\u0627\u0646\u062A \u0642\u064A\u0645\u0629 \u0627\u0644\u062A\u0628\u064A\u064A\u062A \u0633\u0627\u0644\u0628\u0629 \u064A\u062A\u0645 \u062E\u0635\u0645\u0647\u0627 \u0645\u0646 \u0627\u0644\u0635\u0641\u0642\u0629\u060C \u0648\u0641\u064A \u062D\u0627\u0644 \u0643\u0627\u0646\u062A \u0645\u0648\u062C\u0628\u0629 \u064A\u062A\u0645 \u0625\u0636\u0627\u0641\u062A\u0647\u0627 \u0625\u0644\u0649 \u0631\u0635\u064A\u062F \u0627\u0644\u0635\u0641\u0642\u0629.\n    <br><br>\n    \u064A\u062A\u0645 \u0627\u062D\u062A\u0633\u0627\u0628 \u0631\u0633\u0648\u0645 \u0627\u0644\u062A\u0628\u064A\u064A\u062A \u064A\u0648\u0645\u064A\u064B\u0627 \u0641\u064A \u062A\u0645\u0627\u0645 \u0627\u0644\u0633\u0627\u0639\u0629 \u0627\u0644\u0639\u0627\u0634\u0631\u0629 \u0645\u0633\u0627\u0621\u064B \u0628\u062A\u0648\u0642\u064A\u062A \u063A\u0631\u064A\u0646\u062A\u0634 \u0628\u0627\u0633\u062A\u062B\u0646\u0627\u0621 \u0639\u0637\u0644\u0627\u062A \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0648\u062D\u062A\u0649 \u0625\u063A\u0644\u0627\u0642 \u0627\u0644\u0635\u0641\u0642\u0629.\n    <br><br>\n    \u064A\u0631\u062C\u0649 \u0645\u0644\u0627\u062D\u0638\u0629 \u0623\u0646\u0647 \u064A\u062A\u0645 \u0627\u062D\u062A\u0633\u0627\u0628 \u0631\u0633\u0648\u0645 \u062A\u0628\u064A\u064A\u062A \u0645\u0636\u0627\u0639\u0641\u0629 \u064A\u0648\u0645 \u0627\u0644\u0623\u0631\u0628\u0639\u0627\u0621 \u0644\u062A\u063A\u0637\u064A\u0629 \u062A\u0643\u0627\u0644\u064A\u0641 \u0639\u0637\u0644\u0629 \u0646\u0647\u0627\u064A\u0629 \u0627\u0644\u0623\u0633\u0628\u0648\u0639. \u0625\u0630\u0627 \u0643\u0646\u062A \u0645\u0642\u064A\u0645\u064B\u0627 \u0641\u064A \u062F\u0648\u0644\u0629 \u0625\u0633\u0644\u0627\u0645\u064A\u0629\u060C \u064A\u0631\u062C\u0649 \u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u0645\u062F\u064A\u0631 \u062D\u0633\u0627\u0628\u0643 \u0644\u062A\u0641\u0639\u064A\u0644 \u062D\u0633\u0627\u0628 \u062E\u0627\u0644\u064D \u0645\u0646 \u0627\u0644\u062A\u0628\u064A\u064A\u062A \u0627\u0644\u0645\u062A\u0648\u0627\u0641\u0642 \u0645\u0639 \u0627\u0644\u0634\u0631\u064A\u0639\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064A\u0629.",
    forexTextBox4: "\u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0647\u0627\u0645\u0634",
    forexTextBox5: "\u062A\u0639\u062A\u0645\u062F \u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0647\u0627\u0645\u0634 \u0639\u0644\u0649 \u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0627\u0644\u0645\u062D\u062F\u062F. \u062A\u063A\u064A\u064A\u0631 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u064A\u0624\u062F\u064A \u0625\u0644\u0649 \u062A\u063A\u064A\u064A\u0631 \u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0647\u0627\u0645\u0634.",
    //indices
    indicesViewTitle: "\u062A\u062F\u0627\u0648\u0644 \u0627\u0644\u0645\u0624\u0634\u0631\u0627\u062A \u0627\u0644\u0641\u0648\u0631\u064A\u0629",
