    indicesBoxSentence4: "\u062A\u062F\u0627\u0648\u0644 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631 \u0627\u0644\u064A\u0648\u0645",
    indicesBoxSentence5: "\u062A\u062F\u0627\u0648\u0644 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631 24 \u0633\u0627\u0639\u0629",
    indicesBoxSentence6: "\u0623\u0633\u0648\u0627\u0642 \u0639\u0627\u0644\u0645\u064A\u0629 \u062A\u0639\u0645\u0644 \u062F\u0648\u0646 \u062A\u0648\u0642\u0641 \u0645\u0639 \u0633\u0627\u0639\u0627\u062A \u062A\u062F\u0627\u0648\u0644 \u0645\u0631\u0646\u0629",
    indicesBoxSentence7: "\u0628\u062F\u0648\u0646 \u0639\u0645\u0648\u0644\u0627\u062A",
    indicesBoxSentence8: "\u062A\u0643\u0644\u0641\u0629 \u062A\u062F\u0627\u0648\u0644 \u0645\u0646\u062E\u0641\u0636\u0629 \u0628\u062F\u0648\u0646 \u0631\u0633\u0648\u0645 \u0625\u0636\u0627\u0641\u064A\u0629",
    indicesBoxSentence9: "\u0644\u0627 \u064A\u062A\u0645 \u0641\u0631\u0636 \u0623\u064A \u0639\u0645\u0648\u0644\u0627\u062A \u0648\u064A\u062A\u0645 \u062A\u062D\u0642\u064A\u0642 \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u0645\u0646 \u0641\u0631\u0648\u0642 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0641\u0642\u0637",
    indicesBoxSentence10: "\u062A\u062F\u0627\u0648\u0644 \u062B\u0646\u0627\u0626\u064A \u0627\u0644\u0627\u062A\u062C\u0627\u0647",
    indicesBoxSentence11: "\u062A\u062F\u0627\u0648\u0644 \u0639\u0627\u062F\u0644 \u0648\u0634\u0641\u0627\u0641 \u0641\u064A \u0627\u0644\u0627\u062A\u062C\u0627\u0647\u064A\u0646",
    indicesBoxSentence12: "\u0627\u0644\u0627\u0633\u062A\u0641\u0627\u062F\u0629 \u0645\u0646 \u062A\u062D\u0631\u0643\u0627\u062A \u0627\u0644\u0633\u0648\u0642 \u0635\u0639\u0648\u062F\u064B\u0627 \u0648\u0647\u0628\u0648\u0637\u064B\u0627",
