    marketNewsViewTitle: "\u0623\u062E\u0628\u0627\u0631 \u0627\u0644\u0623\u0633\u0648\u0627\u0642, \u0648\u0635\u0648\u0644 \u062E\u0627\u0631\u062C\u064A.",
    marketNewsViewIntro: "\u0646\u0648\u0641\u0631 \u0644\u0643 \u062A\u062D\u062F\u064A\u062B\u0627\u062A \u0641\u0648\u0631\u064A\u0629 \u0644\u0627\u062A\u062C\u0627\u0647\u0627\u062A \u0627\u0644\u0623\u0633\u0648\u0627\u0642 \u0639\u0644\u0649 \u0645\u062F\u0627\u0631 24/7\u060C \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u0623\u062D\u062F\u062B \u0627\u0644\u0623\u062E\u0628\u0627\u0631 \u0645\u0646 \u0623\u0643\u062B\u0631 \u0645\u0646 100 \u062F\u0648\u0644\u0629\u060C \u0644\u062A\u0628\u0642\u0649 \u0639\u0644\u0649 \u0627\u0637\u0644\u0627\u0639 \u062F\u0627\u0626\u0645 \u0628\u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u0633\u0648\u0627\u0642 \u0641\u064A \u0627\u0644\u0648\u0642\u062A \u0627\u0644\u0645\u0646\u0627\u0633\u0628.",
