    economicCalendarViewTitle: "\u0627\u0644\u062A\u0642\u0648\u064A\u0645 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A",
    economicCalendarViewIntro: "\u0627\u0633\u062A\u062E\u062F\u0645 \u0627\u0644\u062A\u0642\u0648\u064A\u0645 \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A \u0644\u0644\u062A\u0639\u0631\u0651\u0641 \u0639\u0644\u0649 \u0623\u0647\u0645 \u0627\u0644\u0623\u062E\u0628\u0627\u0631 \u0648\u0627\u0644\u0623\u062D\u062F\u0627\u062B \u0627\u0644\u0627\u0642\u062A\u0635\u0627\u062F\u064A\u0629 \u0627\u0644\u0645\u0624\u062B\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u0648\u0627\u0642\u060C \u0628\u0627\u0644\u0625\u0636\u0627\u0641\u0629 \u0625\u0644\u0649 \u062A\u0642\u0627\u0631\u064A\u0631 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0627\u0644\u064A\u0629\u060C \u0648\u0627\u0628\u0642\u064E \u0639\u0644\u0649 \u0627\u0637\u0644\u0627\u0639 \u062F\u0627\u0626\u0645 \u0628\u0623\u062D\u062F\u062B \u0645\u0633\u062A\u062C\u062F\u0627\u062A \u0627\u0644\u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u0645\u0627\u0644\u064A\u0629.",
