    worldCup2026HeroSubtitle: "\u0623\u062F\u0631 \u0627\u0644\u0639\u062C\u0644\u0629 \u0648\u0627\u0631\u0628\u062D \u062C\u0648\u0627\u0626\u0632 \u062D\u0635\u0631\u064A\u0629! \u0623\u0643\u0645\u0644 \u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u062A\u0623\u0647\u0644 \u0623\u062F\u0646\u0627\u0647 \u0644\u062A\u0641\u062A\u062D \u0641\u0631\u0635\u062A\u0643 \u0641\u064A \u062A\u062F\u0648\u064A\u0631 \u0639\u062C\u0644\u0629 \u0627\u0644\u062D\u0638.",
    worldCup2026EligibilityLabel: "\u0645\u062A\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0623\u0647\u0644\u064A\u0629",
    worldCup2026EligibilityDepositRequirement: "\u0635\u0627\u0641\u064A \u0625\u064A\u062F\u0627\u0639 \u0628\u0642\u064A\u0645\u0629 10,000 \u062F\u0648\u0644\u0627\u0631 \u0623\u0645\u0631\u064A\u0643\u064A",
    worldCup2026EligibilityTradingRequirement: "\u0625\u0643\u0645\u0627\u0644 50 \u0644\u0648\u062A \u0642\u064A\u0627\u0633\u064A",
    worldCup2026PrizesEyebrow: "\u0645\u0643\u0627\u0641\u0622\u062A \u0645\u0645\u064A\u0632\u0629",
    worldCup2026PrizesTitle: "\u0627\u0631\u0628\u062D \u062C\u0648\u0627\u0626\u0632 \u062D\u0635\u0631\u064A\u0629",
    worldCup2026PrizesSubtitle: "\u0623\u062F\u0631 \u0627\u0644\u0639\u062C\u0644\u0629 \u0644\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0641\u0631\u0635\u0629 \u0627\u0644\u0641\u0648\u0632 \u0628\u0627\u0644\u062C\u0648\u0627\u0626\u0632 \u0627\u0644\u0645\u062E\u062A\u0627\u0631\u0629 \u0627\u0644\u062A\u0627\u0644\u064A\u0629.",
    worldCup2026RulesTitle: "\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0633\u062D\u0628 \u0627\u0644\u0645\u062D\u0638\u0648\u0638",
    worldCup2026RulesIntro: "\u0647\u0630\u0627 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062C \u0645\u062E\u0635\u0635 \u0641\u0642\u0637 \u0644\u0640:",
    worldCup2026Rule1: "\u064A\u062D\u0635\u0644 \u0643\u0644 \u0639\u0645\u064A\u0644 \u0645\u0624\u0647\u0644 \u0639\u0644\u0649 1 \u0641\u0631\u0635 \u062A\u062F\u0648\u064A\u0631 \u062E\u0644\u0627\u0644 \u0641\u062A\u0631\u0629 \u0627\u0644\u062D\u0645\u0644\u0629.",
    worldCup2026Rule3: "\u064A\u062D\u0642 \u0644\u0643\u0644 \u0639\u0645\u064A\u0644 \u0645\u0624\u0647\u0644 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u062C\u0627\u0626\u0632\u0629 \u0648\u0627\u062D\u062F\u0629 \u0641\u0642\u0637 \u0637\u0648\u0627\u0644 \u0645\u062F\u0629 \u0627\u0644\u062D\u0645\u0644\u0629.",
    worldCup2026Rule4: "\u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0633\u062A\u0628\u062F\u0627\u0644 \u0627\u0644\u062C\u0648\u0627\u0626\u0632 \u0646\u0642\u062F\u064B\u0627 \u0623\u0648 \u0628\u0645\u0627 \u064A\u0639\u0627\u062F\u0644\u0647\u0627 \u0645\u0627\u0644\u064A\u064B\u0627 \u062A\u062D\u062A \u0623\u064A \u0638\u0631\u0641.",
    worldCup2026Rule5: "\u0627\u0644\u062C\u0648\u0627\u0626\u0632 \u063A\u064A\u0631 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062A\u062D\u0648\u064A\u0644 \u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u0646\u0642\u0644\u0647\u0627 \u0625\u0644\u0649 \u0634\u062E\u0635 \u0623\u0648 \u062D\u0633\u0627\u0628 \u0622\u062E\u0631.",
    worldCup2026Rule6: "\u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0633\u062A\u0628\u062F\u0627\u0644 \u0627\u0644\u062C\u0648\u0627\u0626\u0632 \u0628\u0639\u0646\u0627\u0635\u0631 \u0623\u062E\u0631\u0649 \u0636\u0645\u0646 \u0645\u062C\u0645\u0648\u0639\u0629 \u0627\u0644\u062C\u0648\u0627\u0626\u0632.",
